namespace{float s_globalTimeScale=1.0F;bool s_globalTimePaused=false;unsigned s_currTimeMs=0;int s_elapsedTimeMs=0;}
void RemoveTranslation(NTempest::C34Matrix&m){m.d0=m.d1=m.d2=0;}void RemoveRotation(NTempest::C34Matrix&m){NTempest::C3Vector s{std::sqrt(m.a0*m.a0+m.a1*m.a1+m.a2*m.a2),std::sqrt(m.b0*m.b0+m.b1*m.b1+m.b2*m.b2),std::sqrt(m.c0*m.c0+m.c1*m.c1+m.c2*m.c2)};m.a0=s.x;m.a1=m.a2=0;m.b0=m.b2=0;m.b1=s.y;m.c0=m.c1=0;m.c2=s.z;}void RemoveScale(NTempest::C34Matrix&m){for(unsigned r=0;r<3;++r){float*d=m.Data()+r*3;float n=std::sqrt(d[0]*d[0]+d[1]*d[1]+d[2]*d[2]);if(n>0){d[0]/=n;d[1]/=n;d[2]/=n;}}}void RemoveRotationAndScaling(NTempest::C34Matrix&m){auto p=NTempest::C3Vector{m.d0,m.d1,m.d2};m={};m.d0=p.x;m.d1=p.y;m.d2=p.z;}void TranslateView(NTempest::C34Matrix&m,const NTempest::C3Vector&v){m.Translate(v);}void RotateView(NTempest::C34Matrix&m,const NTempest::C4Quaternion&q){m.Rotate(q);}void ScaleView(NTempest::C34Matrix&m,const NTempest::C3Vector&v){m.Scale(v);}
void AnimSetTimeScale(CAnim&a,float v){if(a.primarySeq<a.seq.size())a.seq[a.primarySeq].seqTimeScale=v;}float AnimGetTimeScale(const CAnim&a){return a.primarySeq<a.seq.size()?a.seq[a.primarySeq].seqTimeScale:1.0F;}void AnimSetGlobalTimeScale(float v){s_globalTimeScale=v;}float AnimGetGlobalTimeScale(){return s_globalTimeScale;}int WrapAnimTime(int t,int duration){if(duration<=0)return 0;t%=duration;if(t<0)t+=duration;return t;}void SetSequenceTime(CAnim&a,unsigned s,int t){if(s>=a.seq.size()||!a.hdata||s>=a.hdata->seq.size())return;const auto&sequence=a.hdata->seq[s];int duration=sequence.end-sequence.start;if((sequence.flags&1U)!=0)t=std::clamp(t,0,(std::max)(0,duration));else t=WrapAnimTime(t,duration);a.seq[s].elapsed=sequence.start+t;a.seq[s].scaledElapsedTime=a.seq[s].elapsed;}void AnimForceCurrentSequenceTime(CAnim&a,int t){SetSequenceTime(a,a.primarySeq,t);}void AnimResetGlobalSequenceTimes(CAnim&a){std::fill(a.globalSeqElapsed.begin(),a.globalSeqElapsed.end(),0);}NTempest::C34Matrix GetWorldTransform(const CAnim&a,unsigned i){return i<a.status.size()?a.status[i].transform:NTempest::C34Matrix{};}
bool AnimSetSequence(CAnim&a,unsigned s){if(!a.hdata)return false;unsigned resolved=s;if(!a.hdata->sequenceOrder.empty()){if(s>=a.hdata->sequenceOrder.size())return false;resolved=a.hdata->sequenceOrder[s];}if(resolved>=a.hdata->seq.size()||resolved>=a.seq.size()||resolved>=0xFFU)return false;a.primarySeq=static_cast<std::uint8_t>(resolved);a.seq[resolved].elapsed=a.hdata->seq[resolved].start;a.seq[resolved].scaledElapsedTime=a.seq[resolved].elapsed;a.seq[resolved].seqFinished=false;return true;}bool AnimSetRandomSequenceFidget(CAnim&a,unsigned seed){if(!a.hdata||a.hdata->seq.empty())return false;return AnimSetSequence(a,seed%static_cast<unsigned>(a.hdata->seq.size()));}
void AnimAdvanceTime(CAnim&a,unsigned delta){if(a.paused||!a.hdata||a.primarySeq>=a.seq.size()||a.primarySeq>=a.hdata->seq.size())return;a.seqLastTime=a.seq[a.primarySeq].elapsed;auto&s=a.seq[a.primarySeq];const auto&sequence=a.hdata->seq[a.primarySeq];const int duration=sequence.end-sequence.start;const int advance=static_cast<int>(delta*s_globalTimeScale*s.seqTimeScale);const int relative=s.elapsed-sequence.start+advance;const bool crossed=duration>0&&(relative>=duration||relative<0);a.seqLastAdvance=advance;a.sequenceWrapped=(sequence.flags&1U)==0&&crossed;if((sequence.flags&1U)!=0){s.elapsed=sequence.start+std::clamp(relative,0,(std::max)(0,duration));if(!crossed)s.seqFinished=false;}else{s.elapsed=sequence.start+WrapAnimTime(relative,duration);s.seqFinished=false;}s.scaledElapsedTime=s.elapsed;if(crossed&&((sequence.flags&1U)==0||!s.seqFinished)){if((sequence.flags&1U)!=0)s.seqFinished=true;if(s.replayTimes)s.replayTimes--;else CallSeqFinishedHandlers(a,a.primarySeq);}if(!s_globalTimePaused)for(unsigned i=0;i<a.globalSeqElapsed.size();++i){const int d=static_cast<int>(a.hdata->globalSeqLength[i]);a.globalSeqElapsed[i]=d?static_cast<unsigned>(WrapAnimTime(static_cast<int>(a.globalSeqElapsed[i])+advance,d)):0;}AnimAnimateModel(a);}void AnimManualAdvanceTime(CAnim&a,unsigned d){bool p=a.paused;a.paused=false;AnimAdvanceTime(a,d);a.paused=p;}void AnimPauseTime(CAnim&a,bool p){a.paused=p;}
float RandomInRange(float a,float b,unsigned&seed){seed=1664525U*seed+1013904223U;return a+(b-a)*(float(seed&0xFFFFFFU)/float(0x1000000U));}float InvScale(float v){return v!=0?1.0F/v:0;}unsigned PickRandomSequence(const CAnimData&d,unsigned seed){if(d.seq.empty())return~0U;unsigned total=0;for(auto&s:d.seq)total+=s.randPickChance?s.randPickChance:1;unsigned pick=total?seed%total:0;for(unsigned i=0;i<d.seq.size();++i){unsigned w=d.seq[i].randPickChance?d.seq[i].randPickChance:1;if(pick<w)return i;pick-=w;}return 0;}unsigned FindSequenceVariationInUse(const CAnim&a,unsigned s){return s<a.seq.size()&&a.seq[s].useCount?s:~0U;}void CallSeqFinishedHandlers(CAnim&a,unsigned s){if(s<a.seq.size()&&a.seq[s].finished)a.seq[s].finished();if(a.anySeqFinished)a.anySeqFinished();}void SetGlobalSequenceTime(CAnim&a,unsigned s,unsigned t){if(!a.hdata||s>=a.globalSeqElapsed.size())return;unsigned d=a.hdata->globalSeqLength[s];a.globalSeqElapsed[s]=d?t%d:0;}
void AnimPauseGlobalTime(int pause){s_globalTimePaused=pause!=0;}void IAnimInitializeTime(){s_currTimeMs=static_cast<unsigned>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());s_elapsedTimeMs=0;}unsigned IAnimGetCurrTimeMs(){return s_currTimeMs;}unsigned AnimGetElapsedTime(){return static_cast<unsigned>(s_elapsedTimeMs);}void IAnimManualAdvanceTime(CAnim&a,int delta){s_elapsedTimeMs=delta;s_currTimeMs=static_cast<unsigned>(static_cast<int>(s_currTimeMs)+delta);if(delta>=0){AnimManualAdvanceTime(a,static_cast<unsigned>(delta));return;}if(a.primarySeq>=a.seq.size()||!a.hdata||a.primarySeq>=a.hdata->seq.size())return;a.seqLastTime=a.seq[a.primarySeq].elapsed;a.seqLastAdvance=delta;const auto&sequence=a.hdata->seq[a.primarySeq];const int duration=sequence.end-sequence.start;const int relative=a.seq[a.primarySeq].elapsed-sequence.start+delta;a.sequenceWrapped=(sequence.flags&1U)==0&&relative<0;if((sequence.flags&1U)!=0)a.seq[a.primarySeq].elapsed=sequence.start+std::clamp(relative,0,(std::max)(0,duration));else a.seq[a.primarySeq].elapsed=sequence.start+WrapAnimTime(relative,duration);a.seq[a.primarySeq].scaledElapsedTime=a.seq[a.primarySeq].elapsed;if(!s_globalTimePaused)for(unsigned i=0;i<a.globalSeqElapsed.size();++i){const int d=static_cast<int>(a.hdata->globalSeqLength[i]);a.globalSeqElapsed[i]=d?static_cast<unsigned>(WrapAnimTime(static_cast<int>(a.globalSeqElapsed[i])+delta,d)):0;}AnimAnimateModel(a);}
bool CAnimBoneObj::IsVisible(const CAnim*a)const{return geosetId==0xFF||(a&&geosetId<a->geosetStatus.size()&&a->geosetStatus[geosetId].alpha>0.0F);}
void AdvanceTime(CAnim&a,unsigned d){AnimAdvanceTime(a,d);}bool SetSequence(CAnim&a,unsigned s){return AnimSetSequence(a,s);}float Length(const NTempest::C3Vector&v){return std::sqrt(v.SquaredMag());}
int GetSeqSyncTime(const CAnim&a,unsigned current,unsigned previous){if(!a.hdata||current>=a.hdata->seq.size()||previous>=a.hdata->seq.size()||previous>=a.seq.size())return 0;const auto&oldSequence=a.hdata->seq[previous];const int oldDuration=oldSequence.end-oldSequence.start;const int newDuration=a.hdata->seq[current].end-a.hdata->seq[current].start;if(oldDuration<=0||newDuration<=0)return 0;return static_cast<int>((static_cast<long long>(WrapAnimTime(a.seq[previous].elapsed-oldSequence.start,oldDuration))*newDuration)/oldDuration);}
void ISetSequenceInfo(CAnim&a,unsigned sequence,bool resetTime){if(sequence>=a.seq.size())return;auto&s=a.seq[sequence];++s.useCount;s.seqFinished=false;if(resetTime){int start=a.hdata&&sequence<a.hdata->seq.size()?a.hdata->seq[sequence].start:0;s.elapsed=start;s.scaledElapsedTime=start;s.replayTimes=0;}}void ISetSequence(CAnim&a,unsigned sequence,unsigned previous,bool resetTime){if(sequence>=a.seq.size())return;int sync=resetTime?0:GetSeqSyncTime(a,sequence,previous);ISetSequenceInfo(a,sequence,resetTime);a.primarySeq=static_cast<std::uint8_t>(sequence);SetSequenceTime(a,sequence,sync);}void ISetSequenceReset(CAnim&a,unsigned sequence,unsigned blendTime,bool resetTime){(void)blendTime;ISetSequence(a,sequence,a.primarySeq,resetTime);}void SetObjectSequences(CAnim&a,unsigned sequence,unsigned previous,unsigned blendTime,bool resetTime){(void)blendTime;ISetSequence(a,sequence,previous,resetTime);}void SetObjectSequencesReset(CAnim&a,unsigned sequence,unsigned blendTime,bool resetTime){ISetSequenceReset(a,sequence,blendTime,resetTime);}void SetSplitBodySequence(CAnim&a,unsigned objectId,unsigned sequence,int flags){if(objectId>=a.status.size()||sequence>=a.seq.size())return;a.status[objectId].lockedSequence=sequence;if((flags&1)!=0)SetSequenceTime(a,sequence,0);}
